/**
 * ExportInvoicesExcelV1Request
 *
 * Export invoices to a spreadsheet. `format` selects the content layout (`SUMMARY` one row per invoice, `ITEMS` one row per line) and `file_format` the file type (`xlsx` or `csv`). Narrow the selection with `date_from`/`date_to`, `client_id`, `series_id` or `invoice_ids`, or omit them to export everything.
 */
export type ExportInvoicesExcelV1Request = {
    /**
     * Invoice status to filter by (draft, sent, paid, overdue, cancelled, annulled, scheduled).
     */
    status?: 'draft' | 'scheduled' | 'sent' | 'paid' | 'cancelled' | 'overdue' | 'annulled';
    /**
     * Start of the issue-date range (inclusive).
     */
    date_from?: string | null;
    /**
     * End of the issue-date range (inclusive).
     */
    date_to?: string | null;
    /**
     * Client ID (UUID v7 value) to filter invoices by.
     */
    client_id?: string | null;
    /**
     * Series ID (UUID v7 value) to filter invoices by.
     */
    series_id?: string | null;
    /**
     * Free-text search term (number, recipient, series).
     */
    search?: string | null;
    /**
     * Content layout: SUMMARY (one row per invoice) or ITEMS (one row per line).
     */
    format?: 'SUMMARY' | 'ITEMS';
    /**
     * Formato de fichero: xlsx o csv.
     */
    file_format?: 'xlsx' | 'csv';
    /**
     * List of invoice IDs (UUID v7 values) to export. If omitted, exports the set matching the filters.
     */
    invoice_ids?: Array<string> | null;
};

/**
 * FaceSubmission
 *
 * A submission of an invoice to FACe (the Spanish B2G general entry point). Tracks the FACe registry number and the processing status reported by the FACe web service.
 */
export type FaceSubmission = {
    /**
     * UUID (v7) of the FACe submission.
     */
    id: string;
    object: 'face_submission';
    /**
     * UUID (v7) of the submitted invoice.
     */
    invoice_id: string;
    /**
     * FACe processing status (`submitted`, `registered_rcf`, `accounted`, `paid`, `rejected`, `cancellation_requested`, `cancelled`, `error`). Kept up to date by the system polling — there is no refresh endpoint in v1.
     */
    status: string;
    /**
     * Registry number assigned by FACe on presentation. Synthetic `FACE-SANDBOX-*` for sandbox (test key) submissions.
     */
    registry_number: string | null;
    /**
     * DIR3 code of the accounting office (oficina contable, role 01) snapshotted at submission time.
     */
    dir3_accounting_office: string;
    /**
     * DIR3 code of the managing body (órgano gestor, role 02) snapshotted at submission time.
     */
    dir3_managing_body: string;
    /**
     * DIR3 code of the processing unit (unidad tramitadora, role 03) snapshotted at submission time.
     */
    dir3_processing_unit: string;
    /**
     * Local transmission error code, `null` unless the submission is in `error` state.
     */
    error_code: string | null;
    /**
     * Human-readable transmission error message (in Spanish), `null` unless the submission is in `error` state.
     */
    error_message: string | null;
    /**
     * When the processing status last changed (ISO 8601).
     */
    status_updated_at: string;
    /**
     * When the system last polled FACe for this submission, or `null` if never polled yet.
     */
    last_polled_at: string | null;
    created_at: string;
};

/**
 * FieldIssue
 *
 * A single per-field issue (error or warning) of a bulk/import row, in the `{param, code, message}` shape of the multi-field error model.
 */
export type FieldIssue = {
    /**
     * Name of the affected field, or `null` when the issue is not tied to a specific field.
     */
    param: string | null;
    /**
     * Machine-readable code for the field issue (stable across languages).
     */
    code: string;
    /**
     * Human-readable description of the issue, in Spanish.
     */
    message: string;
};

